advanced.solutionCode:
#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;
    long long f = 1;
    for (int i = 2; i <= n; ++i)
        f *= i;
    int digits = 0;
    do {
        ++digits;
        f /= 10;
    } while (f);
    cout << digits;
}
